import { expect, test } from '@playwright/test'
import { openStory } from './story'

// Component rows (28 §4, step s33): the restyled base components and the kit pieces s33 owns, at
// one desktop viewport. Inline stories render side by side, Night Rehearsal beside Daylight, so
// one image holds both themes; popups portal to <body> and are captured once per theme. These are
// the G2 baselines; the Screens/ rows in screens.spec.ts are regenerated by each screen step.

type Row = { name: string; story: string; popup?: boolean }

const SIDE_BY_SIDE: Row[] = [
  { name: 'button', story: 'base-button--all-states' },
  { name: 'button-icons', story: 'base-button--icon-buttons' },
  { name: 'toggle', story: 'base-toggle--all-states' },
  { name: 'tabs', story: 'base-tabs--all-states' },
  { name: 'form', story: 'base-form-controls--all-states' },
  { name: 'choice-cards', story: 'base-form-controls--choice-cards' },
  { name: 'slider', story: 'base-slider--all-states' },
  { name: 'number-field', story: 'base-numberfield--default' },
  { name: 'display', story: 'base-display--all-states' },
  { name: 'overlay-triggers', story: 'base-overlays--all-states' },
  { name: 'transport', story: 'kit-transportbutton--all-states' },
  { name: 'drop-zone', story: 'kit-import--drop-zone-states' },
  { name: 'save-status', story: 'kit-savestatus--all-states' },
  { name: 'coach-mark', story: 'kit-onboarding--coach-both-themes' },
  { name: 'brand', story: 'brand-marks-and-icons--both-themes' },
  { name: 'icons', story: 'brand-marks-and-icons--icons-both-themes' },
]

const POPUPS: Row[] = [
  { name: 'menu', story: 'base-overlays--menu-open' },
  { name: 'select', story: 'base-overlays--select-open' },
  { name: 'popover', story: 'base-overlays--popover-open' },
  { name: 'tooltip', story: 'base-overlays--tooltip-with-shortcut' },
  { name: 'dialog', story: 'base-dialog--open-night' },
  { name: 'alert-dialog', story: 'base-dialog--alert' },
  { name: 'drawer', story: 'base-drawer--bottom' },
  { name: 'toast', story: 'base-toast--with-undo' },
  { name: 'toast-error', story: 'base-toast--error-state' },
]

test.describe('components', () => {
  test.use({ viewport: { width: 1440, height: 900 }, hasTouch: false, isMobile: false })

  for (const row of SIDE_BY_SIDE) {
    test(`${row.name} side by side`, async ({ page }) => {
      await openStory(page, row.story)
      await expect(page).toHaveScreenshot(`component-${row.name}--both.png`, { fullPage: true })
    })
  }

  for (const row of POPUPS) {
    for (const appearance of ['dark', 'light'] as const) {
      test(`${row.name} ${appearance}`, async ({ page }) => {
        await openStory(page, row.story, `appearance:${appearance}`)
        await expect(page).toHaveScreenshot(`component-${row.name}--${appearance}.png`)
      })
    }
  }
})
